'use strict'

const { Transform } = require('node:stream')
const prettifyLogObject = require('./prettify-log-object')

function prettify (customPrettifiers, colorize) {
  return new Transform({
    autoDestroy: true,
    objectMode: true, // means it accepts and products objects (i.e., produce String instead of Buffer)
    transform (logObject, _enc, next) {
      try {
        next(null, prettifyLogObject(logObject, customPrettifiers, colorize) + '\n')
      } catch (err) {
        next(err)
      }
    },
  })
}

module.exports = prettify
